    private atualizarRegiao():void {const r=REGIOES_REINO[this.faseAtual];if(r.id!==this.regiaoAtual){this.regiaoAtual=r.id;this.textoRegiao.setText(`FASE ${this.faseAtual+1} • ${r.nome.toUpperCase()}`).setAlpha(0);this.tweens.add({targets:this.textoRegiao,alpha:1,duration:260});}const p=progressoPorMarcos(this.nivel,this.cavaleiro.x,this.cavaleiro.y,this.portas.filter(porta=>porta.aberta).length),restantes=this.inimigos.filter(i=>!i.derrotado&&!i.guardiao).length;this.textoInimigos.setText(restantes?`AMEAÇAS NO CAMINHO: ${restantes}`:'CAMINHO SEGURO!');this.barraProgresso.setSize(Math.max(1,300*p),9).setTint(r.corDestaque);}
